#!/bin/sh
# Registers ssx shortcuts as GNOME custom keybindings (generated by ssx).
set -e
gsettings set org.gnome.settings-daemon.plugins.media-keys.custom-keybinding:/org/gnome/settings-daemon/plugins/media-keys/custom-keybindings/ssx-capture-region/ name ''\''Capture region'\'''
gsettings set org.gnome.settings-daemon.plugins.media-keys.custom-keybinding:/org/gnome/settings-daemon/plugins/media-keys/custom-keybindings/ssx-capture-region/ command ''\''ssx capture region'\'''
gsettings set org.gnome.settings-daemon.plugins.media-keys.custom-keybinding:/org/gnome/settings-daemon/plugins/media-keys/custom-keybindings/ssx-capture-region/ binding ''\''<Control><Shift>s'\'''
gsettings set org.gnome.settings-daemon.plugins.media-keys.custom-keybinding:/org/gnome/settings-daemon/plugins/media-keys/custom-keybindings/ssx-capture-screen/ name ''\''ssx capture screen'\'''
gsettings set org.gnome.settings-daemon.plugins.media-keys.custom-keybinding:/org/gnome/settings-daemon/plugins/media-keys/custom-keybindings/ssx-capture-screen/ command ''\''ssx capture screen'\'''
gsettings set org.gnome.settings-daemon.plugins.media-keys.custom-keybinding:/org/gnome/settings-daemon/plugins/media-keys/custom-keybindings/ssx-capture-screen/ binding ''\''Print'\'''
gsettings set org.gnome.settings-daemon.plugins.media-keys.custom-keybinding:/org/gnome/settings-daemon/plugins/media-keys/custom-keybindings/ssx-record-title-my-clip/ name ''\''/usr/local/bin/ssx record --title \'\''My clip\'\'''\'''
gsettings set org.gnome.settings-daemon.plugins.media-keys.custom-keybinding:/org/gnome/settings-daemon/plugins/media-keys/custom-keybindings/ssx-record-title-my-clip/ command ''\''/usr/local/bin/ssx record --title \'\''My clip\'\'''\'''
gsettings set org.gnome.settings-daemon.plugins.media-keys.custom-keybinding:/org/gnome/settings-daemon/plugins/media-keys/custom-keybindings/ssx-record-title-my-clip/ binding ''\''<Alt><Super>r'\'''
gsettings set org.gnome.settings-daemon.plugins.media-keys.custom-keybinding:/org/gnome/settings-daemon/plugins/media-keys/custom-keybindings/ssx-sh-c-notify-send-ssx-done-home-a776b4d2/ name ''\''Hostile: quotes, $, ; and #'\'''
gsettings set org.gnome.settings-daemon.plugins.media-keys.custom-keybinding:/org/gnome/settings-daemon/plugins/media-keys/custom-keybindings/ssx-sh-c-notify-send-ssx-done-home-a776b4d2/ command ''\''sh -c \'\''notify-send \'\''\\\'\''\'\''ssx\'\''\\\'\''\'\'' "done: $HOME"; echo 100% # ok, really\'\'' \'\''arg with spaces\'\'''\'''
gsettings set org.gnome.settings-daemon.plugins.media-keys.custom-keybinding:/org/gnome/settings-daemon/plugins/media-keys/custom-keybindings/ssx-sh-c-notify-send-ssx-done-home-a776b4d2/ binding ''\''<Control><Alt><Shift><Super>F12'\'''
gsettings set org.gnome.settings-daemon.plugins.media-keys.custom-keybinding:/org/gnome/settings-daemon/plugins/media-keys/custom-keybindings/ssx-capture-window-delay-2/ name ''\''ssx capture window \'\''--delay=2\'\'''\'''
gsettings set org.gnome.settings-daemon.plugins.media-keys.custom-keybinding:/org/gnome/settings-daemon/plugins/media-keys/custom-keybindings/ssx-capture-window-delay-2/ command ''\''ssx capture window \'\''--delay=2\'\'''\'''
gsettings set org.gnome.settings-daemon.plugins.media-keys.custom-keybinding:/org/gnome/settings-daemon/plugins/media-keys/custom-keybindings/ssx-capture-window-delay-2/ binding ''\''<Super>grave'\'''
gsettings set org.gnome.settings-daemon.plugins.media-keys.custom-keybinding:/org/gnome/settings-daemon/plugins/media-keys/custom-keybindings/ssx-n-c-d/ name ''\''ssx \'\''ünïcödé 日本語\'\'''\'''
gsettings set org.gnome.settings-daemon.plugins.media-keys.custom-keybinding:/org/gnome/settings-daemon/plugins/media-keys/custom-keybindings/ssx-n-c-d/ command ''\''ssx \'\''ünïcödé 日本語\'\'''\'''
gsettings set org.gnome.settings-daemon.plugins.media-keys.custom-keybinding:/org/gnome/settings-daemon/plugins/media-keys/custom-keybindings/ssx-n-c-d/ binding ''\''XF86AudioMute'\'''
gsettings set org.gnome.settings-daemon.plugins.media-keys custom-keybindings '['\''/org/gnome/settings-daemon/plugins/media-keys/custom-keybindings/custom0/'\'', '\''/org/gnome/settings-daemon/plugins/media-keys/custom-keybindings/ssx-capture-region/'\'', '\''/org/gnome/settings-daemon/plugins/media-keys/custom-keybindings/ssx-capture-screen/'\'', '\''/org/gnome/settings-daemon/plugins/media-keys/custom-keybindings/ssx-record-title-my-clip/'\'', '\''/org/gnome/settings-daemon/plugins/media-keys/custom-keybindings/ssx-sh-c-notify-send-ssx-done-home-a776b4d2/'\'', '\''/org/gnome/settings-daemon/plugins/media-keys/custom-keybindings/ssx-capture-window-delay-2/'\'', '\''/org/gnome/settings-daemon/plugins/media-keys/custom-keybindings/ssx-n-c-d/'\'']'
